        _name = "LOOPSDAO";
        _symbol = "LPD";
        project = _project;
        _mint(tokenReceiver, 210000000e18);
        pair = IPancakeFactory(FACTORY_ADDRESS).createPair(
            USDC_ADDRESS,
            address(this)
